"          {isPaymentModalOpen && (() => {
             const billNo = selectedTable ? (tableBillNumbers[selectedTable.id] || nextBillNo) : nextBillNo;
             const activeTableBill = selectedTable ? [...(tableBills[selectedTable.id] || []), ...(tableCarts[selectedTable.id] || [])] : [];
             const isFreeMode = selectedPaymentMode.toLowerCase() === 'free';
             const totals = calculateTotals();
             const calculatedTotal = isFreeMode ? 0 : totals.total;
             const discountAmt = isFreeMode ? 0 : totals.discountAmt;
             const couponDiscountAmt = isFreeMode ? 0 : totals.couponDiscountAmt;
             const pointsDiscountAmt = isFreeMode ? 0 : totals.pointsDiscountAmt;

             const fullCustPhone = customerPhone ? (customerPhone.startsWith('+') ? customerPhone : customerCountryCode + customerPhone) : '';
             const custRecord = fullCustPhone ? customerDb[fullCustPhone] : null;
             const custBalance = custRecord ? (parseFloat(custRecord.balance) || 0) : 0;
             const oldDue = custBalance < 0 ? Math.abs(custBalance) : 0;

             const numericTip = isFreeMode ? 0 : (parseFloat(tipAmount) || 0);
             const grandTotal = calculatedTotal + numericTip;

             let advancePaid = 0;
             let netAmountToPayToday = grandTotal;
             if (editingPreOrder) {
               advancePaid = parseFloat(editingPreOrder.advance_paid) || 0;
               netAmountToPayToday = Math.max(0, grandTotal - advancePaid);
             }

             const totalOutstanding = netAmountToPayToday + oldDue;
             const numericPaid = parseFloat(customerPaidAmount) || 0;
             const returnAmount = numericPaid > totalOutstanding ? numericPaid - totalOutstanding : 0;"

